INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1099070-che306', 'stk-azeezo', 'CHE 306', 'info', '{"desc": "**جودة المقرر بشكل عام\nالمقرر مفيد من ناحية تعريفه ل (speration procrss) بس افضل يكون لو ان يكون له مادة اخرى تتابع مجراه\nالمواضيع التي يغطيها المقرر\nمفيدة من ناحية تعلقها بالمصانع و اكثر التطبيقات الحاصلة في انتاج oil تبدأ و تنتهي بالفصل بين المركبات من ناحية المواد الخفيفة و الثقيلة\nالكتاب المستخدم للمقرر\nمفيد جدا و مناسب ولكنه يفتقر للأمثلة\nالأسئلة والأمثلة المستخدمة في المقرر\nمناسبة و تشرح بشكل ممتاز ولكن تحتاج الى زيادة عددها و تنوعها\nمدى فائدته في الناحية التطبيقية\nمن ناحية انتاج oil في المملكة كما ذكرت سابقا العملية تبدأ بفصل المركبات عن بعضها و تنتهي بفصل المنتجات عن بعضها لذلك انا ارى ان هذه المادة مفيدة جدا و ذات تأثير كبير في مجال الoil\n\nإضافة يمكن ما لها علاقة بالمادة ولكن احب اذكرها\nالمادة هذي بحسب ما سمعت ان في اغلب السمسترات يسوون حركة مساعدة للطلاب و هي انهم يعدلون درجة ميجر 1 اذا جبت درجة اعلى في ميجر 2 (مع ابقاء افرج ميجر 1 بدون تغير ) حركة لمساعدة الطلاب بس شوي تصعب الحصول على القريدات العالية\nيعني في كلاسنا ولا واحد قدر يجيب A+ و السبب ان الأفرج كان مرتفع. و ايضا في كلاسنا الدرجات تكاد تكون اما A او C+\n**", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-306-stagewise-operations/120654/2", "user": "azeezo", "ts": 1348664266000, "tid": 120654, "pn": 2}}', 1348664266000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1199251-che306', 'stk-chemist', 'CHE 306', 'info', '{"desc": "جودة المقرر بشكل عام:\nهذا الكورس من أساسيات التخصص وهو عملية الفصل بين المواد\n\nالمواضيع التي يغطيها المقرر:\n1) الفصل بين مادتين\n2) الفصل بين ثلاث مواد أو أكثر\n3) حالات خاصه للفصل\n4) Absorption & Stripping Column\n5) Extraction with a solvent\n6) Batch column\n\nالكتاب المستخدم للمقرر:\nوالله مو ذاك الزود بفتقد إلى كثير من الأمثلة الإفتراضية والواقعية يفتقد أيضا إلى الرسوم التوضيحية. يعني مو سيئ مرة ولكن يمشي الحال.\n\nالأسئلة والأمثلة المستخدمة في المقرر:\nقليله جدا خاصة الأمثلة\n\nمن أسهل الكورسات في الهندسة الكيميائية كورس قريد لا تفوته عليك 👍", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-306-stagewise-operations/120654/5", "user": "Chemist", "ts": 1363224031000, "tid": 120654, "pn": 5}}', 1363224031000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1432510-che306', 'stk-_3111', 'CHE 306', 'info', '{"desc": "المادة تتكلم عن عمليات الفصل وأغلبها يركز على الدستليشن، بداية المادة بسيطة والكونسيبت حلو فيها ويمكن في آخر المتيريل يقل هذا شوي.\n\nغالبا يدرس المادة الدكاترة: حبيب العلي ومحمد أمين وأحيانا أبوالسعود والبغلي بشكل أقل والنظام فيها يشبه 201 يعني ورقتك بتعدي على الكل وقت التصحيح وكل دكتور بيحط سؤال\nأفضل مصدر للمذاكرة هو نوت الدكتور علي الشامي (متيريل ميجر 1 و2) والكتاب\n\nموفقين\n\n((نادي الهندسة الكيميائية))", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-306-stagewise-operations/120654/6", "user": "_3111", "ts": 1446939851000, "tid": 120654, "pn": 6}}', 1446939851000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1452911-che306', 'stk-medoalkebsi', 'CHE 306', 'info', '{"desc": "ماحتكلم كثير الشباب ماقصرو.\n\nلكن , الكورس سهل كانه 201+202. اهم شي تعرف كيف تسوي ماتيريال بلنس + بيسك انرجي بلنس.\n\nالكونسبت الجديد ماهو صعب وقليل. من اسهل كورسات الهندسه الكيميائيه حتى الان.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-306-stagewise-operations/120654/7", "user": "Medoalkebsi", "ts": 1467249101000, "tid": 120654, "pn": 7}}', 1467249101000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1467016-che306', 'stk-k_94', 'CHE 306', 'info', '{"desc": "جودة المقرر بشكل عام\n\nفرع مهم جدا من فروع الهندسة الكيميائية , لكنه يركز كثير عالديستليشن وما يركز على باقي عمليات الseparation\n\nالكتاب المستخدم للمقرر\nسيئ الصراحة حشو كلام وناقصه امثلة , بس كويس السلوشن متوفر 😆\n\nالأسئلة والأمثلة المستخدمة في المقرر\n\nقليلة وبعضها فيها اخطاء بالارقام\n\nمدى فائدته في الناحية التطبيقية\n\nمهمة جدا للي بيشتغل في ريفاينري لكن الصراحة من اصعب مواد الهندسة الكيميائية اللي اخذتها , درستها عند الدكتور ممدوح الحارثي وهذي اول مره يدرسها والدكتور غير متمكن منها حقيقة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-306-stagewise-operations/120654/8", "user": "K_94", "ts": 1485379997000, "tid": 120654, "pn": 8}}', 1485379997000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1486840-che306', 'stk-user9534', 'CHE 306', 'info', '{"desc": "كتابها أسؤأ كتاب في هذا التخصص\nالكونسبت حقها ماهو صعب، يمكن ماتيريال الفاينل هو اللي كان آصعب شيء\nتعتبر من آهم المواد في التخصص لأنها تشرح لك آلية الفصل وخصوصاً في آبراج التقطير\n\nفي الرابط سلايدات + مانيوال سلوشن للكتاب\n306 files - Download - 4shared", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-306-stagewise-operations/120654/9", "user": "user9534", "ts": 1517082951000, "tid": 120654, "pn": 9}}', 1517082951000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1533240-che306', 'stk-user11325', 'CHE 306', 'info', '{"desc": "Che 306- separation process- semester 211\n\nالمادة تتكلم عن فصل المواد ابتداءً من مادتين الى عدة مواد، الكورس مهتم بخمس تقنيات لفصل المواد اللي هم :\n\n-Flash Distillation\n\n-Distillation column\n\n-Batch Distillation (ينسحب عيه اخر السمستر اذا ضاق الوقت عالدكاترة هههه)\n\n- Absorption\n\n-Stripping\n\n- Liquid-liquid extraction\n\nاللحين بلخص لكم السيلبس حق الكورس عالسريع عشان تعرفوا السالفة\n\nChapter 2:\n\nيتكلم عن الفلاش ديستليشن (فصل بين مادتين فقط) شابتر قصير لكن ممكن يكون صعب لانه مقدمة للكورس يحتاج تشتغل عليه شويتين\n\nChapter 3:\nشابتر سهل ويعتبر مقدمة للشابتر اللي بعده\n\nChapter 4:\nأطول شابتر واكثرهم دسامة ، يتكلم عن فصل المواد داخل أبراج التقطير اللي تشوفوها بالجبيل وينبع، وبتعرف الفرق بين المواد اللي تقعد اسفل برج التقطير والمواد اللي تكون اعلى البرج\n\nChapter 5:\nيسمونه الsharp distilation شابتر سهل وقصير لكن الكونسبت حقه غير مُحبذ في الصناعة\n\nChapter 7:\nشابتر سهل لكن مهم، مشابه لشابتر 5 لكنه افضل منه كفكرة\n\nChapter 9:\nيتكلم عن ال Batch distilation مادرسناه بسبب ضيق الوقت لان الكورس طويل لكن سوينا عنه مشروع عليه 10 درجات\n\nChapter 10:\nشابتر مهم راح تدرس كيف تحسب ال flooding velocity عشان تقيس قُطر (Diameter) برج التقطير كله تعويض مباشر لا تشيل هم\n\nChapter 12:\nفي هذا الشابتر راح تدرس نوعين جديدين لفصل المواد\n1- Absorption\nلمن يكون عندك غاز فيه مركب تبغى تستخلصه فتستخدم سائل معين غالبًا يكون الماء عشان تسحبه من الغاز وطبعًا فيه شروط بتدرسوها\n\n2- stripping\nعكس اللي قبل لكن يكون عندك سائل فيه مركب معين تبغى تستخرجه فتستخدم غاز يسحب المركب من السائل\n\nعموما الشابتر ذا هو المفضل بالنسبة لي بصراحة\n\nChapter 13: Liquid-Liquid extraction\nاخر شابتر، نفس الطريقة اللي كنت تسويها في شابتر 12 بتطبقها في 13، هذا الشابتر يتكلم عن فصل السائل عن طريق سائل اخر، الشابتر قصير وسهل\n\nاهم المهارات اللي لازم تمتلكها عشان تجيب درجات عالية بالكورس هو:\n1- ماس و انيرجي بالانس : حتى لو ماكنت متمكن فيهم في che200/201 راح تتعلمها هنا فلا تخاف بس شد حيلك\n\n2- قراءة الcharts/ graphs:مهارة بسيطة لكن مهمة عشان تاخذ الخصائص اللي تحتاجها عشان تحل الاسئلة\n\n3- الرسم البياني، بتحتاجه عشان تحدد عدد المنصات /stages اللازمة لفصل المواد. يعني لا تنسى مسطرتك\nبالاختبار\n\n4- اسئلة الكتاب مهمة مهمة مهمة\n\n5- بعض الدكاترة يجيب اسئلة كونسبت فانتبه لا تتورط مثلي بالميجر ههههه\n\n6- قبل الميجر لاتنسى تحل اسئلة الكويزات احيانًا تتكرر افكاره\n\nالكورس هذا مهم جدًا وبنفس الوقت سهل بس احتمال تتعب معه شوي بالبداية وموفقين ان شاء الله", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-306-stagewise-operations/120654/10", "user": "user11325", "ts": 1641076058000, "tid": 120654, "pn": 10}}', 1641076058000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1540752-che306', 'stk-mohammed_al-hajji', 'CHE 306', 'info', '{"desc": "TERM 251| Dr.Bassim Abussaud\n\nملخص وافي للكورس موجود في هذا الرد :\n\nميزة هذا الكورس أنه متخصص أكثر من باقي الكورسات الماضية ويركز فقط وفقط على فصل المواد وهذا يخليه مترابط المواضيع وسهل الاعتماد فيه على معلوماتك الأولية من بداية الكورس.\n\nبمصادرك يمديك تعتمد على فيديوهات شرح د باسم لو تبي تراجع أو ما فهمت من دكتورك وطبعِا شرحه غني عن الوصف، وجميل لو ترجع لنوتاته بعد وقت\n\nمذاكرتك.\n\nوهنا صورة تقسم لكم مقاطعه حق كل شابتر:\n\nIMG-20251212-WA0005955×1439 44.2 KB\n\nاعتمذت في مذاكرتي على الهوموركات والأولد ميجرز القديمة وأيضًا المسائل الموجودة بالنوتس.\n\nالدكتور كان أحيانًا يشطح بالأسئلة من مسائل وكونسبت فيبي لك تهتم بالكونسبت بعد والي بيفيدك أصلًا بعدين في الكارير.\n\n، بشكل عام الكورس سهل لكن بنفس الوقت يبي له شغل وحل، على ترمنا كان الكورس 3 مياجر وفاينل وبدون كويزات، أصل الكورس ستاندرد لكن على ترمنا بسبب الأفرجات خلوه أفرج.\n\nوموفقين جميعًا.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-306-stagewise-operations/120654/11", "user": "Mohammed_Al-Hajji", "ts": 1766933555348, "tid": 120654, "pn": 11}}', 1766933555348, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-k_94-che306', 'stk-k_94', 'CHE 306', 'doc', '{"docs": [{"id": "stk-dr-f98538", "n": "Dr. Mamdoh Al-Harthi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE 306- Term 161\nالتحضير : يحضر بداية الكلاس وما يدقق عالتاخير ويسمح بالحضور لسكشن ثاني , وما اعتقد يعطي DN لانه واحد من الشباب غاب 9 غيابات وما اخذ حرمان ولكن لا تفلها بزيادة\n\nالكويزات : الكوزات كان عليها 20% الترم هذا واحنا اختبرنا 9 , يعني الكوز وزنه حول 2.1% !!! , يعني ذاكر زييييييين ولا بتندم , بالعادة كوزاته من الاسئلة اللي يقول لكم تمرنوا عليها واذا حاول يسوي تريك يجيب لك من امثلة الكتاب 😅\n\nالمياجر: الترم هذا خلاه ميدتيرم عليه 35% وكان جدا صعب وصارت نقاشات كثير لانه في جزئية ما شرحها وجاب عليها سؤال وزنه عالي ( موجودة الجزئية بالكتاب ) والافرج كان 50% ( الدكتور السمستر هذا يدرسها لحاله )\n\nالفاينلات: 40% وكان فيه كونسبت T/F , و MCQ مسائل و كونسبت ( الMCQ كانت من اسئلة الكتاب )وكان فيه ثلاث مسائل ثنتين سهله ووحدة جدا صعبة وكانت من الامثلة اللي اخر شابتر الabsorption اعتقد كان شابتر 12 او 11\n\nالشرح : يقرا من سلايدات وللاسف الكتاب جدا سيئ والمادة تحتاج واحد فاهمها صح والدكتور اول مره يدرسها وشرحه ابدا غير مناسب\n\n----\n\nبالرغم ان شرح الدكتور سيئ للمادة الا انه اسئلته ابدا مو قد شرحه وعانينا كثيييير معه , عطانا 5 اسايمنتات وتفاجانا نهاية الترم انه اعطى اصفار كثير فيها يقول انا ما عمري قلت لكم انه مسموح تشتغلون سوا بالرغم انه ب CHE300 اشتغلنا بقروبات ولا قال شي !! , والمشكلة انتظر لنهاية الترم عشان يعلمنا , عطانا فرصة نسويها مره ثانية ولكن معد اعطانا الدرجات بعد التعديل\n+\n\nالدكتور جدا سيئ للمادة بالرغم ان قريداته مو بطالة بالنسبة للدرجات , ولكن وش فايدة القريد اذا قعدنا نعاني مع الكورس الترم كله وطلعنا منه زي ما دخلنا ؟!\n\nطبعا زي الCHE300 الدكتور ما علمنا كم اخذنا بالفاينل وفاجانا بالقريد بالبورتال كعادة دكاترة الCHE\n\n------\n\nما انصح فيه ب CHE306", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1467020-che306", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mamdoh-al-harthi/98538/17", "user": "K_94", "ts": 1485382604000, "tid": 98538, "pn": 17}}]}', 1485382604000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ali-che-che306', 'stk-ali-che', 'CHE 306', 'doc', '{"docs": [{"id": "stk-dr-f98538", "n": "Dr. Mamdoh Al-Harthi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE306\nبنود التقييم :\n\nالتحضير : يحضر بداية الكلاس او بنص الكلاس , غير متشدد في التحضير ويسمح بالحضور بالسكشن الثاني.\nطريقة الشرح : يقرأ من السلايدات ويجيب لك النوم ومايحل الامثله يقولك سهله حلهم بنفسك, معظم الطلاب تنشغل بالجوال.\nاشوف الدكتور غير متمكن من ناحيه طريقه شرحه للمادة.\nالكويزات : 9 الى 10 كويزات من اسئلة الكتاب يحددها لك قبل الكويز بسبوع.\nالمياجر: ميد تيرم 3 مسائل 30% … سؤال منهم ماتكلم عن فكرته وكان عليه كم كبير من الدرجات. الافرج 50%+ الوقت كان غير كافي.\nالفاينلات : 40%… كونسبت 3 اسئلة + 3 مسائل … مسألتين طوال بالحل ومسألة سهله. + الوقت كان ايضا غير كافي…\nالقريد النهائي: D+\nالصوت: واضح\nإضافات : الدكتور خلوق ومرن بعض الشيء انصح فيه في 300 فقط.\nاما 306 مادة مهمة وتحتاج دكتور يعرف كيف يوصلك المعلومة…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1467804-che306", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mamdoh-al-harthi/98538/18", "user": "Ali-CHE", "ts": 1486408356000, "tid": 98538, "pn": 18}}]}', 1486408356000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahmed1-che306', 'stk-ahmed1', 'CHE 306', 'doc', '{"docs": [{"id": "stk-dr-f98542", "n": "Dr. B Abussaud", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE 306 - Term 222\nالتحضير:\nينادي الطلاب بالسريال نمبر في بداية الكلاس، يحضر يوميا بس حذف غيابين في نهاية الترم ولا عنده مشكلة في التأخير.\n\nطريقة الشرح :\nشرحه حلو ولطيف من النوتات الخاصة فيه بالإضافة الى ان شرحه الرائع موجود في اليوتيوب على قناته، احيانا حسيته يقدر يشرح اكثر في بعض المواضيع بس مشى عليها بسرعة، وللمعلومية الدكتور يشرح الماتيريال بسرعة فلا تسوف كثير.\nالكويزات:\nسهلة جدا جدا جدا، مجرد تطبيق للي شرحه الدكتور.\nالميد:\nالمادة كومن و الميد مستواه متوسط يميل للسهولة.\n\nالفاينل:\nكومن وكان سهل.\n\nالتقييم النهائي:\nA+\n\nاضافات:\nالدكتور يكفيه اخلاقه عدا ان شرحه ممتاز، حاول تنزل عنده هالمادة وبترتاح.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536740-che306", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/b-abussaud/98542/53", "user": "Ahmed1", "ts": 1686157289000, "tid": 98542, "pn": 53}}]}', 1686157289000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user4576-che306', 'stk-user4576', 'CHE 306', 'doc', '{"docs": [{"id": "stk-dr-f98550", "n": "Dr. Habib Al-Ali", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "المادة CHE306\n\nلتحضير: يومي اول الكلاس ويدقق على الغياب\n\nطريقة الشرح : يعطيك زبدة الزبده بس المشكله مايكتب على السبوره الا شي بسيط، طبعا لازم يشطح عن\nالشرح حبتين ويخش بسوالف مال امها داعي\n\nالكوزات: مافي الا واحد على خبري وشفوي\n\nهوم ورك كل اسبوعين تقريبا\n\nالمياجر والفاينلات: كومن\n\nمن الاخر الدكتور مزاجي واخلاق لك عليها وتصحيح شديد جدا يعني انسى partial لو شي بسيط لكن الحسنه الوحيده انه يلمح عن اسئلة الاختبار اذا تبي قريد بيطلع عينك. افضل د.محمد امين اذا وجد", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1233998-che306", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/habib-al-ali/98550/12", "user": "user4576", "ts": 1370897961000, "tid": 98550, "pn": 12}}]}', 1370897961000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9221-che306', 'stk-user9221', 'CHE 306', 'doc', '{"docs": [{"id": "stk-dr-f98550", "n": "Dr. Habib Al-Ali", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 132 - CHE 306\n\nبنود التقييم :\n\nالتحضير :\n\nغريب نوعاً ما ،، تشوفه يشد على شعبة في التحضير وفي الشعبة الثانية ما يحضر !!؟\n\nطريقة الشرح :\n\nيرسم الـ distillation column ويسوي مراجعة خفيفة ع الدرس السابق وبعدين ينتقل لموضوع درس اليوم وعادي عنده يخلص المحاضرة على إقزامبل واحد واعتقد إن ما قد جلسنا 50 دقيقة إلا على عدد أصابع اليد الواحدة ،، بقية المحاضرات يمشينا بعد نص ساعة أو حتى أقل ،، الحلو فيه يعطيك الزبدة وما يدخل في التفاصيل اللي مالها داعي\n\nالكويزات :\n\nاختبرنا 6 كويزات في أول ثلاث أسابيع وكلهم كانوا مااااي وآخر السمستر قال إني حسبت درجة الكويزات بونص للكل\n\nالمياجر:\n\nكومون وسؤاله دائماً أسهل سؤال\n\nالفاينلات :\n\nنفس المياجر\n\nالقريد النهائي:\n\nاعطيه B\n\nالصوت:\n\nواضح\n\nإضافات :\n\nاللي يجيب في الاختبار الأول والثاني درجة كاملة يعلق على اسمه إلى نهاية السمستر واحتمال يقوله لا تحضر الفاينل 😲", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1374882-che306", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/habib-al-ali/98550/16", "user": "user9221", "ts": 1401528133000, "tid": 98550, "pn": 16}}]}', 1401528133000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_3111-che306', 'stk-_3111', 'CHE 306', 'doc', '{"docs": [{"id": "stk-dr-f98550", "n": "Dr. Habib Al-Ali", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE 306 - 142\n\nالتحضير : يحضر غالبا ويقل هذا في نهاية الفصل\nطريقة الشرح : ما يتعمق، اللي مو معك ما يركز عليه وهذا جيد فقط الأشياء المهمة هي اللي يشرحها بالتفصيل، أنا كنت معتمد بشكل كبير على السيلف ستدي وطلعت بقريد جيد ومرضي\nالكويزات : لا يوجد وهذا شي رهيييييييييييييييييييييييييييييييييييييييييييب\nالمياجر: الميجر الأول والثاني جاب سؤال يبين بوضوح الفاهم من الحافظ في الميجر الثاني كان في فكرة صعبة في السؤال والجواب الصح تقوله أن هذه الحالة مستحيلة لكنه مشى في التصحيح\nالفاينلات : بسيط وأظنه خلاه كذا لأنه كان قبل تسليم العلامات بيوم ونص تقريبا\nالقريد النهائي: اعطيه b+\nالصوت: عالي وواضح\nإضافات : الرجل شايب، لا تتفلسف عليه و تسوي نفسك فاهم وأنت مضيع، لا تتكلم ولا تلعب بجوالك، 99% ما بتستفيد لو راجعت تصحيحه فلا تتعب نفسك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1422932-che306", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/habib-al-ali/98550/17", "user": "_3111", "ts": 1437854856000, "tid": 98550, "pn": 17}}]}', 1437854856000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abo_fauzi-che306', 'stk-abo_fauzi', 'CHE 306', 'doc', '{"docs": [{"id": "stk-dr-f98550", "n": "Dr. Habib Al-Ali", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE 306 - Term 162\n\nالتحضير : يومياً نهاية الكلاس … مايحب المتأخرين وأحياناً يكلمهم ويفصل عليهم لكن وقت التحضير الظاهر انه يحضرهم\n\nطريقة الشرح : الكلاس غالباً 20-30 دقيقة نصها … شرحه من وجهة نظري جداً سيء , يقولك السؤال اللي يحله ويحط النواتج والنهائية ويقلك لازم تروح تذاكر بنفسك وتحل السؤال بنفسك … يعني بصراحة شرحه لا يودي ولا يجيب ولازم المادة تقلبها سيلف ستدي … طبعاً هذا غير انو لازم كل كلاس يقعد يتكلم عالزواج وعن تنطيط آدم 🤪\n\nالكويزات : ماعنده كويزات\n\nالمياجر: ميجر 1 و 2 كانت كومن بينه وبين د.ممدوح الحارثي … ميجر 1 كان سهل مرة لكن ميجر 2 جاء متوسط مائل للصعوبة\nالدكتور تصحيحه دمااااار خطأ بسيط ممكن يطير عليك درجة السؤال كامل للأسف\n\nالفاينلات : الفاينل كان متوسط\n\nالقريد النهائي: D\n\nالصوت: واضح\n\nإضافات : يقال والعلم عند الله انو ترم 162 كان أخر ترم للدكتور وبعده حيتقاعد … لو فعلاً كلام صحيح فالحمد لله لأنو الترم ذا خسفنا جداً في القريدات في النهاية الصراحة وكثيرين أنظلموا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474252-che306", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/habib-al-ali/98550/21", "user": "Abo_Fauzi", "ts": 1496262727000, "tid": 98550, "pn": 21}}]}', 1496262727000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-che306', 'stk-guest', 'CHE 306', 'doc', '{"docs": [{"id": "stk-dr-f98554", "n": "Dr. Mohamed Amin", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Che 306\n\nشرحه : يعني يمشي الحااااال على السبورة\nلكن نوووته بطل\n\nالهوموركات … على كل شابتر و يحل الهومورك في الكلاس\nانت بس انقش الحل و سلمه :d\n\nلا لا لا لا لا لا لا لا لا للغياب\n\nلو انت تستحق b+ و عندك غياب راح تأخذ c\n\nو صارت لواحد من الشباب آعرفه الترم الماضي\n\nلا تراجع تصحيح المياجر معه لان تصحيحه مزاجي\n\nو على نفسيته يوم يصحح ورقتك\n\nو مياجره مطابقة للهومورك و اكزامبل النوت\nو أحيانا يكرر مياجر قديمة بنفس الارقام\nو لما اخذت معه جاب ميجر سؤال هومورك بنفس الارقام\n\nالصوت : ضعيف نوعا ما\n\nتقييم : C", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p742354-che306", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohamed-amin/98554/3", "user": "Guest", "ts": 1292142789000, "tid": 98554, "pn": 3}}]}', 1292142789000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-chemist-che306', 'stk-chemist', 'CHE 306', 'doc', '{"docs": [{"id": "stk-dr-f115329", "n": "Dr. Ali Alshami", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE 306 Term 121\n\nالتحضير:\nنص الترم حضر ونص الباقي ماحضر يعني اذا تذكر أو اشتهى حضر وما يحاسب على التأخير ان شاء الله تيجي 7:30 ما عنده مشكلة\n\nالشرح:\nكويس وهو من الدكاتره اللي شرحهم وسط يعني مو شريح مرة ومو زفت مرة وكذلك حله للمسائل\n\nالكويزات:\nسهلة نوعا ما\n\nالمياجر والفاينال:\nكومون\n\nمميزات الدكتور:\n1) قمة في الأخلاق والتعامل\n2) المرونة في مواعيد تسليم الواجبات والكويزات\n\nالسلبيات:\nيفتقد لتنظيم وقت الشرح فتشوفه يتكلم في أشياء ثانية او يطول في شرح نقطة ويعطيها وقت أكثر من اللزوم وفي نهاية الكلاس تشوفه مستعجل يبي يخلص الدرس ودائما يأخذ من البريك وقت لابأس به علشان يخلص الدرس 😐\n\nقريد الدكتور النهائي :\nB", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1164735-che306", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ali-alshami/115329/13", "user": "Chemist", "ts": 1358282300000, "tid": 115329, "pn": 13}}]}', 1358282300000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user4150-che306', 'stk-user4150', 'CHE 306', 'doc', '{"docs": [{"id": "stk-dr-f115329", "n": "Dr. Ali Alshami", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "che 306\n\nالدكتور علي له كلمة في المادة قالها في أحد الفصول سأضل أتذكرها دائماً\n\nas easy as you want as difficult as you want\n\nفهو يريدك أن تفهم المادة ببساطة ولكن على حساب (في بعض الأحيان) الجهد\nالذي تبذله أنت في فهم بعض المبادئ التي قد لا تكون واضحة في الشرح ,\nولكن ثق تماماً اذا فهمت المادة فسوف تخرج منها بدرجة عالية لأن اختباراتهم مباشرة وسهلة,\nفي الامتحان النهائي خرج مجموعة من الطلاب في منتصف الوقت أو بعده بقليل !\nالدكتور علي في هذه المادة بالذات يركز على كم مبدأ ويعيد ويزيد فيهم\nيهتم في فهمك الهندسي والعلمي للعملية\nأخلاقه جميلة وتعامله راقي ومرن , متواجد في مكتبه حتى خارج أوقات المكتب المحددة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1165064-che306", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ali-alshami/115329/14", "user": "user4150", "ts": 1358362897000, "tid": 115329, "pn": 14}}]}', 1358362897000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user3068-che306', 'stk-user3068', 'CHE 306', 'doc', '{"docs": [{"id": "stk-dr-f115332", "n": "Dr. Housam Binous", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت معه che306 في 102\n\nالتحضير : دائما في بدايت الكلاس\nطريقة الشرح : سلايدات وعلى البورد\nالكويزات : كوزين وكانو سهلين ومن شرحه\nالمياجر: كومون (ما ادري ليه الي قبلي قال انه يخسف بس انا اشوفه عادي مثل اي دكتور يعني يعطيك حقك ولا درجه زياده)\nالفاينلات : كومون\nالقريد النهائي: في che306 انا اعطيه a\n\nاضافات: في العادة ماراح تفهم شيء في الكلاسات بس اذا جاء يحل الهوموورك ولا اسئلة الكتاب راح تفهم الزبده والمهم\n\nذاكر الاسئله الي يحلها في الكلاس والي في الكتاب والمياجر تصير سهله\nالصوت:", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p937910-che306", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/housam-binous/115332/3", "user": "user3068", "ts": 1322367901000, "tid": 115332, "pn": 3}}]}', 1322367901000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-aaaaaaa-che306', 'stk-aaaaaaa', 'CHE 306', 'doc', '{"docs": [{"id": "stk-dr-f115332", "n": "Dr. Housam Binous", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE306-161\nالتحضير : كل يوم\nالشرح : يشرح من السلايدات و يستخدم السبوره للدريفيشن و يحل مسائل\nكويزات : سهله و غالبا من الواجبات او يكون حل مثلها في الكلاس(الكويزات كانت كلاس كامل و OpenBook)\nالصوت : ممتاز\nالمياجر : متوسطه\nملاحظه : انتبه في الكلاس ، كان يلمح عن اسئلة الاختبار دايم (تقدر تقول انه يعلمك اي سؤال يجي)\nالتقيم : A", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1475956-che306", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/housam-binous/115332/11", "user": "aaaaaaa", "ts": 1499288931000, "tid": 115332, "pn": 11}}]}', 1499288931000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
